// 铁律：
// 1. 没有任何 API 能控制调度器
// 2. 调度没有任何公平/顺序保证，线程可能「饿死」
// 3. 不要把程序正确性建立在特定调度行为上（跨平台、不可复现）
// 4. 正确的并发代码 = 对任何调度交错都正确

import java.util.concurrent.*;
class PredictableLatch {
  public static void main(String[] args) {
    ExecutorService executor = Executors.newSingleThreadExecutor();
    CountDownLatch latch = new CountDownLatch(1);        // 数 1 个事件
    executor.execute(() -> waitForLatchThenPrint(latch));// 把 latch 传给新线程的工作
    System.out.println("back in main");                  // main 干完事件
    latch.countDown();                                    // 发信号：计数 1→0，放行等待者
    executor.shutdown();
  }
  private static void waitForLatchThenPrint(CountDownLatch latch) {
    try { latch.await(); }                                // 等到计数归零（期间不可运行，不占 CPU）
    catch (InterruptedException e) { e.printStackTrace(); }
    System.out.println("top o' the stack");
  }
}
