import java.io.*;
import java.net.InetSocketAddress;
import java.nio.channels.Channels;
import java.nio.channels.SocketChannel;
import java.nio.charset.StandardCharsets;
public class DailyAdviceClient {
  public void go() {
    InetSocketAddress serverAddress = new InetSocketAddress("127.0.0.1", 5000);
    // try-with-resources：代码块结束后自动 close socketChannel（无论正常还是异常）
    try (SocketChannel socketChannel = SocketChannel.open(serverAddress)) {
      Reader channelReader = Channels.newReader(socketChannel, StandardCharsets.UTF_8);
      BufferedReader reader = new BufferedReader(channelReader);
      String advice = reader.readLine();   // 和读文件的 readLine 完全一样！
      System.out.println("Today you should: " + advice);
      reader.close();
    } catch (IOException e) {
      e.printStackTrace();
    }
  }
  public static void main(String[] args) { new DailyAdviceClient().go(); }
}

// Code Magnets 答案：PingingClient（每秒发一条 ping，共 10 条）
import java.io.*;
import java.net.InetSocketAddress;
import java.nio.channels.*;
import java.time.format.FormatStyle;
import java.util.concurrent.TimeUnit;
import static java.nio.charset.StandardCharsets.UTF_8;
import static java.time.LocalDateTime.now;
import static java.time.format.DateTimeFormatter.ofLocalizedTime;
public class PingingClient {
  public static void main(String[] args) {
    InetSocketAddress server = new InetSocketAddress("127.0.0.1", 5000);
    try (SocketChannel channel = SocketChannel.open(server)) {
      PrintWriter writer = new PrintWriter(Channels.newWriter(channel, UTF_8));
      System.out.println("Networking established");
      for (int i = 0; i < 10; i++) {
        String message = "ping " + i;
        writer.println(message);
        writer.flush();                                  // 别忘了 flush！
        String currentTime = now().format(ofLocalizedTime(FormatStyle.MEDIUM));
        System.out.println(currentTime + " Sent " + message);
        TimeUnit.SECONDS.sleep(1);                       // 每秒一条
      }
    } catch (IOException | InterruptedException e) {      // 多 catch：两种异常同样处理
      e.printStackTrace();
    }
  }
}
